#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` for this app.

Run from the project root AFTER `flutter create --platforms=android .`:
  * adds INTERNET and POST_NOTIFICATIONS permissions to the main manifest
  * sets minSdk to 23 (flutter_secure_storage requires >= 23)
  * enables core library desugaring (required by flutter_local_notifications)
Handles both build.gradle (Groovy) and build.gradle.kts (Kotlin DSL).
Safe to run twice. Untested against every Flutter version: check the diff.
"""
import pathlib
import re
import sys

root = pathlib.Path("android")
manifest = root / "app/src/main/AndroidManifest.xml"
if not manifest.exists():
    sys.exit("android/ not found - run `flutter create --platforms=android .` first")

m = manifest.read_text(encoding="utf-8")
for perm in ("android.permission.INTERNET", "android.permission.POST_NOTIFICATIONS"):
    if perm not in m:
        m = m.replace("<application", f'<uses-permission android:name="{perm}"/>\n    <application', 1)
manifest.write_text(m, encoding="utf-8")

kts = root / "app/build.gradle.kts"
groovy = root / "app/build.gradle"
if kts.exists():
    g = kts.read_text(encoding="utf-8")
    g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", g)
    if "isCoreLibraryDesugaringEnabled" not in g:
        g = re.sub(r"(compileOptions\s*\{)", r"\1\n        isCoreLibraryDesugaringEnabled = true", g, count=1)
    if "desugar_jdk_libs" not in g:
        if re.search(r"^dependencies\s*\{", g, re.M):
            g = re.sub(r"^(dependencies\s*\{)", r'\1\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")', g, count=1, flags=re.M)
        else:
            g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
    kts.write_text(g, encoding="utf-8")
elif groovy.exists():
    g = groovy.read_text(encoding="utf-8")
    g = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", g)
    if "coreLibraryDesugaringEnabled" not in g:
        g = re.sub(r"(compileOptions\s*\{)", r"\1\n        coreLibraryDesugaringEnabled true", g, count=1)
    if "desugar_jdk_libs" not in g:
        if re.search(r"^dependencies\s*\{", g, re.M):
            g = re.sub(r"^(dependencies\s*\{)", r"\1\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'", g, count=1, flags=re.M)
        else:
            g += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
    groovy.write_text(g, encoding="utf-8")
else:
    sys.exit("no app/build.gradle(.kts) found")
print("android project patched")
